begin;
create extension if not exists pgtap;
select plan(9);
select has_function('public','create_physical_reservation_atomic',array['jsonb','jsonb'],'physical reservation RPC exists');
select function_privs_are('public','create_physical_reservation_atomic',array['jsonb','jsonb'],'authenticated',array['EXECUTE'],'authenticated can execute');
select function_privs_are('public','create_physical_reservation_atomic',array['jsonb','jsonb'],'anon',array[]::text[],'anon cannot execute');
insert into auth.users(id,email,encrypted_password,raw_app_meta_data,raw_user_meta_data) values ('b3000000-0000-4000-8000-000000000001','physical-owner@example.test','x','{}','{}');
insert into public.users(id,email,display_name,auth_user_id) values ('b3000000-0000-4000-8000-000000000001','physical-owner@example.test','Physical Owner','b3000000-0000-4000-8000-000000000001');
insert into public.organizations(id,name,slug,status,timezone) values ('b3000000-0000-4000-8000-000000000010','Physical Org','physical-org','active','UTC');
insert into public.roles(id,name,slug,permissions) values ('b3000000-0000-4000-8000-000000000020','Editor','physical-editor',array['reservation.create']);
insert into public.profiles(id,user_id,organization_id,role_id,display_name) values ('b3000000-0000-4000-8000-000000000030','b3000000-0000-4000-8000-000000000001','b3000000-0000-4000-8000-000000000010','b3000000-0000-4000-8000-000000000020','Physical Owner');
insert into public.venues(id,organization_id,name,status) values ('b3000000-0000-4000-8000-000000000040','b3000000-0000-4000-8000-000000000010','Physical Venue','active');
insert into public.resources(id,venue_id,type,name,capacity,status) values ('b3000000-0000-4000-8000-000000000050','b3000000-0000-4000-8000-000000000040','Mesa','Physical Table',5,'active');
insert into public.events(id,organization_id,name,event_type,status,start_at,timezone,venue,capacity,operational_model,venue_id) values ('b3000000-0000-4000-8000-000000000060','b3000000-0000-4000-8000-000000000010','Physical Event','event','draft','2026-10-01','UTC','Physical Venue',5,'table_based','b3000000-0000-4000-8000-000000000040');
insert into public.event_layouts(id,event_id,venue_id,name,status) values ('b3000000-0000-4000-8000-000000000070','b3000000-0000-4000-8000-000000000060','b3000000-0000-4000-8000-000000000040','Physical Layout','active');
insert into public.event_layout_resources(id,event_layout_id,type,name,capacity,status,source_resource_id) values ('b3000000-0000-4000-8000-000000000080','b3000000-0000-4000-8000-000000000070','Mesa','Physical Table',5,'active','b3000000-0000-4000-8000-000000000050');
select set_config('request.jwt.claims','{"sub":"b3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((public.create_physical_reservation_atomic(jsonb_build_object('id','b3000000-0000-4000-8000-000000000090','event_id','b3000000-0000-4000-8000-000000000060','resource_id','b3000000-0000-4000-8000-000000000050','code','PHY-1','name','Physical Reservation','date','2026-10-01','time','20:00'),jsonb_build_array(jsonb_build_object('id','b3000000-0000-4000-8000-000000000091','guest_name','Guest 1'),jsonb_build_object('id','b3000000-0000-4000-8000-000000000092','guest_name','Guest 2')))->'reservation'->>'resource_id'),'b3000000-0000-4000-8000-000000000050','authoritative resource returned');
select is((select count(*)::int from public.guests where reservation_id='b3000000-0000-4000-8000-000000000090'),2,'all guests inserted atomically');
select is((select string_agg(invitation_code,',' order by access_ordinal) from public.guests where reservation_id='b3000000-0000-4000-8000-000000000090'),'PHY-1-01,PHY-1-02','ordinals and invitation codes allocated');
select throws_ok($$select public.create_physical_reservation_atomic(jsonb_build_object('id','b3000000-0000-4000-8000-000000000099','event_id','b3000000-0000-4000-8000-000000000060','resource_id','b3000000-0000-4000-8000-000000000050','code','PHY-BAD','name','Bad','date','2026-10-01','time','20:00'),jsonb_build_array(jsonb_build_object('id','b3000000-0000-4000-8000-000000000093','guest_name',null)))$$,'23502',NULL,'invalid guest rolls back');
select is((select count(*)::int from public.reservations where id='b3000000-0000-4000-8000-000000000099'),0,'failed reservation leaves no row');
select throws_ok($$select public.create_physical_reservation_atomic(jsonb_build_object('id','b3000000-0000-4000-8000-000000000098','event_id','b3000000-0000-4000-8000-000000000060','resource_id','b3000000-0000-4000-8000-000000000050','code','PHY-FULL','name','Full','date','2026-10-01','time','20:00'),jsonb_build_array(jsonb_build_object('guest_name','1'),jsonb_build_object('guest_name','2'),jsonb_build_object('guest_name','3'),jsonb_build_object('guest_name','4'),jsonb_build_object('guest_name','5'),jsonb_build_object('guest_name','6')))$$,'22023','physical_capacity_exceeded','capacity is enforced');
select * from finish();
rollback;
